 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1120;
       --panel: rgba(15, 23, 42, 0.9);
       --panel-border: rgba(148, 163, 184, 0.22);
       --text: #e5eefc;
