  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your full name.';
          }

          if (value.trim().length < 2) {
            return 'Error: Enter your full name using at least 2 characters.';
          }

          return '';
        }
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your email address.';
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Error: Enter a valid email address, such as name@example.com.';
          }

          return '';
        }
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return '';
          }

          const phonePattern = /^\+?\d{7,15}$/;
          if (!phonePattern.test(trimmedValue)) {
            return 'Error: Enter a phone number with 7 to 15 digits and an optional leading +.';
