 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="support-card" aria-labelledby="support-heading">
       <p class="eyebrow">Support</p>
       <h1 id="support-heading">Contact our support team</h1>
       <p class="intro">Share your details and we will reach out as soon as we can to help with your request.</p>

       <form id="support-form" novalidate>
         <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-required="true"
             aria-describedby="full-name-error"
             aria-errormessage="full-name-error"
           >
           <p id="full-name-error" class="error-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="email"
             type="email"
             inputmode="email"
             autocomplete="email"
             required
             aria-required="true"
             aria-describedby="email-address-error"
             aria-errormessage="email-address-error"
           >
           <p id="email-address-error" class="error-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             inputmode="tel"
             autocomplete="tel"
             aria-describedby="phone-number-help phone-number-error"
             aria-errormessage="phone-number-error"
           >
           <p id="phone-number-help" class="helper-text">Optional. Use digits only, with an optional leading +, for example +14155550123.</p>
           <p id="phone-number-error" class="error-message" hidden></p>
         </div>

         <button type="submit">Send support request</button>
         <p id="form-status" class="status-message" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const statusMessage = document.getElementById('form-status');

     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your full name.';
           }

           if (value.trim().length < 2) {
             return 'Error: Enter your full name using at least 2 characters.';
           }

           return '';
         }
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your email address.';
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return 'Error: Enter a valid email address, such as name@example.com.';
           }

           return '';
         }
       },
       {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return '';
           }

           const phonePattern = /^\+?\d{7,15}$/;
           if (!phonePattern.test(trimmedValue)) {
             return 'Error: Enter a phone number with 7 to 15 digits and an optional leading +.';
           }

           return '';
         }
       }
     ];

     function setFieldState(field, message) {
       const hasError = Boolean(message);
       field.input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
       field.error.textContent = message;
       field.error.hidden = !hasError;
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldState(field, message);
       return !message;
     }

     fields.forEach((field) => {
       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (!field.error.hidden) {
           validateField(field);
         } else {
           field.input.setAttribute('aria-invalid', 'false');
         }

         statusMessage.textContent = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       statusMessage.textContent = '';

       let firstInvalidField = null;

       fields.forEach((field) => {
         const isValid = validateField(field);
         if (!isValid && !firstInvalidField) {
           firstInvalidField = field.input;
         }
       });

       if (firstInvalidField) {
         firstInvalidField.focus();
         statusMessage.textContent = 'Please correct the highlighted fields and try again.';
         return;
       }

       statusMessage.textContent = 'Support request ready to send.';
       form.reset();
       fields.forEach((field) => setFieldState(field, ''));
     });
   </script>
